   142	// sameWorktreePath compares two worktree paths after filepath.Clean. Both
   143	// paths come from paths.WorktreeRoot, so an exact-bytes match is expected in
   144	// the common case; Clean is defense-in-depth against trailing slashes and
   145	// duplicate separators.
   146	func sameWorktreePath(a, b string) bool {
