   150	// adoptPendingReviewMarkerInto reads any pending review marker and applies it
   151	// to the given session state. Returns (newState, modified, error). If the
   152	// state already has Kind set (e.g., a subsequent turn of a review session),
   153	// the marker is left in place and modified=false — adoption only happens on
   154	// first tag. The marker is cleared on successful first adoption.
   155	//
   156	// Worktree scoping: when the marker carries a WorktreePath, only a session
   157	// whose own WorktreePath matches will adopt it. This prevents a Claude
   158	// session in worktree A from racing to claim a marker that was meant for a
   159	// session `entire review` just launched in worktree B (both worktrees share
   160	// the same .git/entire-sessions/ directory where the marker lives).
   161	// Pre-fix markers with no WorktreePath fall back to unscoped adoption.
   162	func adoptPendingReviewMarkerInto(ctx context.Context, s session.State) (session.State, bool, error) {
   163		// Already tagged — don't re-apply on subsequent turns.
   164		if s.Kind != "" {
   165			return s, false, nil
   166		}
   167		m, ok, err := ReadPendingReviewMarker(ctx)
   168		if err != nil {
   169			return s, false, err
   170		}
   171		if !ok {
   172			return s, false, nil
   173		}
   174		if m.WorktreePath != "" && !sameWorktreePath(m.WorktreePath, s.WorktreePath) {
   175			// Marker belongs to a different worktree — leave it for the session
   176			// `entire review` actually spawned, which will reach its own hook
   177			// and claim the marker.
   178			return s, false, nil
   179		}
   180		s.Kind = session.KindAgentReview
   181		s.ReviewSkills = m.Skills
   182		if err := ClearPendingReviewMarker(ctx); err != nil {
   183			// Tagging succeeded; leftover marker self-heals on next session start
   184			// (since Kind is now set, the next turn will return modified=false
   185			// and the marker will be re-cleared on any next review session).
   186			logging.Warn(ctx, "failed to clear pending review marker", slog.String("error", err.Error()))
   187		}
   188		return s, true, nil
   189	}
