   601	func gitLines(ctx context.Context, repoRoot string, args ...string) ([]string, error) {
   602		full := append([]string{"-C", repoRoot}, args...)
   603		output, err := exec.CommandContext(ctx, "git", full...).Output()
   604		if err != nil {
   605			return nil, fmt.Errorf("git %s: %w", strings.Join(args, " "), err)
   606		}
   607		trimmed := strings.TrimSpace(string(output))
   608		if trimmed == "" {
   609			return nil, nil
   610		}
   611		lines := strings.Split(trimmed, "\n")
   612		result := lines[:0]
   613		for _, line := range lines {
   614			if line = strings.TrimSpace(line); line != "" {
   615				result = append(result, line)
   616			}
   617		}
   618		return result, nil
   619	}
