   701	func formatReviewBriefTable(rows []reviewBriefRow) string {
   702		const (
   703			commitHeader     = "commit"
   704			checkpointHeader = "checkpoint"
   705			filesHeader      = "files"
   706			agentHeader      = "agent"
   707			subjectHeader    = "subject"
   708		)
   709	
   710		commitWidth := len(commitHeader)
   711		checkpointWidth := len(checkpointHeader)
   712		filesWidth := len(filesHeader)
   713		agentWidth := len(agentHeader)
   714		for _, row := range rows {
   715			commitWidth = max(commitWidth, len(row.commit))
   716			checkpointWidth = max(checkpointWidth, len(row.checkpoint))
   717			filesWidth = max(filesWidth, len(strconv.Itoa(row.files)))
   718			agentWidth = max(agentWidth, len(row.agent))
   719		}
   720	
   721		var sb strings.Builder
   722		sb.WriteString("Commits in scope (newest first):\n\n")
   723		fmt.Fprintf(&sb, "  %-*s  %-*s  %*s  %-*s  %s\n",
   724			commitWidth, commitHeader,
   725			checkpointWidth, checkpointHeader,
   726			filesWidth, filesHeader,
   727			agentWidth, agentHeader,
   728			subjectHeader)
   729		for _, row := range rows {
   730			fmt.Fprintf(&sb, "  %-*s  %-*s  %*d  %-*s  %s\n",
   731				commitWidth, row.commit,
   732				checkpointWidth, row.checkpoint,
   733				filesWidth, row.files,
   734				agentWidth, row.agent,
   735				row.subject)
   736		}
   737		sb.WriteString("\n")
   738		sb.WriteString("Use checkpoint IDs and commit hashes to inspect details:\n")
   739		sb.WriteString("  - `entire explain <id>` (for example `entire explain ")
   740		sb.WriteString(firstCheckpointExample(rows))
   741		sb.WriteString("`)\n")
   742		sb.WriteString("  - `entire explain <id> --raw-transcript` (for example `entire explain ")
   743		sb.WriteString(firstCheckpointExample(rows))
   744		sb.WriteString(" --raw-transcript`) for the raw checkpoint transcript\n")
   745		sb.WriteString("  - `git show <commit>` for the commit diff\n")
   746		return sb.String()
   747	}
