+func renderReviewBriefForRepo(ctx context.Context, repoRoot string, scope reviewScope) (brief string) {
+	defer func() {
+		if r := recover(); r != nil {
+			logging.Debug(ctx, "review brief: panic while rendering for repo", slog.Any("panic", r))
+			brief = ""
