+func truncateReviewSubject(subject string) string {
+	const maxSubjectLength = 64
+	subject = strings.TrimSpace(subject)
+	if len(subject) <= maxSubjectLength {
+		return subject
+	}
+	return strings.TrimSpace(subject[:maxSubjectLength-3]) + "..."
+}
