+		if metadata == nil {
+			continue
+		}
+		if session.Kind(metadata.Kind).IsReview() {
+			continue
+		}
+		if metadata.Agent == "" {
+			continue
+		}
+		ag, err := agent.GetByAgentType(metadata.Agent)
+		if err != nil {
+			return string(metadata.Agent)
+		}
+		return string(ag.Name())
+	}
+	return "-"
